      contraindications: combine(thiazideCommon.contraindications, ["The current label contraindicates anuria and hypersensitivity to indapamide or other sulfonamide-derived drugs. Severe hepatic disease increases encephalopathy risk from electrolyte disturbance."]),
      nursingEssentials: combine(thiazideCommon.nursingEssentials, ["Do not infer safety from a modest urine response. Trend sodium and potassium after initiation and titration because vascular pressure benefit and electrolyte toxicity can diverge."]),
      interactions: thiazideCommon.interactions,
      keyLabs: thiazideCommon.keyLabs,
      nclexTraps: combine(thiazideCommon.nclexTraps, ["Indapamide's vascular effects help blood pressure, but it remains an NCC blocker capable of severe sodium and potassium disturbance."]),
      populationRisks: populationRisks("Pediatric safety is not established for routine U.S. use.", "Older adults have heightened hyponatremia, orthostasis, and arrhythmia risk; use conservative dosing and early laboratory checks.", "Use only when benefit justifies fetal and maternal-volume risk; review lactation because thiazide-like diuresis can reduce milk production."),
      sourceNote: "Current U.S. indapamide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=deb83f97-6c61-4a09-bed6-18dcf1183405",
