      nursingEssentials: combine(thiazideCommon.nursingEssentials, ["For IV use, verify reconstitution, compatibility, line, rate, recent loop exposure, and a defined urine-response window. The route solves absorption, not monitoring."]),
      interactions: combine(thiazideCommon.interactions, ["Concurrent loop therapy is often intentional but sharply increases depletion risk; neuromuscular blockers and antihypertensives may have greater effects."]),
      keyLabs: thiazideCommon.keyLabs,
